package com.mentality.forgewebmap.web;
import com.mentality.forgewebmap.config.*;import com.mentality.forgewebmap.player.*;import com.mentality.forgewebmap.player.PlayerMarkerService.PlayerInfo;import com.mentality.forgewebmap.render.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class ApiHandlersTest{@TempDir Path d;TestHttpExchange c(com.sun.net.httpserver.HttpHandler h,String p)throws Exception{TestHttpExchange e=new TestHttpExchange("GET",p);h.handle(e);assertEquals("application/json; charset=utf-8",e.h.getFirst("Content-Type"));return e;}ApiBiomeHandler b(ApiBiomeHandler.BiomeLookup l,boolean up){return new ApiBiomeHandler(l,()->up,1);}@Test void playerMarkersDisabledReturnsEmptyArray()throws Exception{PlayerMarkerService s=new PlayerMarkerService();s.publish(List.of(new PlayerInfo("secret","overworld",1,2,3,4)));s.setEnabled(false);assertEquals("[]",c(new ApiPlayersHandler(s),"/api/players").body());}@Test void playerMarkersEnabledSerializesSnapshot()throws Exception{PlayerMarkerService s=new PlayerMarkerService();s.publish(List.of(new PlayerInfo("Alex","the_end",1.5,64,2.25,90)));String x=c(new ApiPlayersHandler(s),"/api/players").body();assertTrue(x.contains("\"name\":\"Alex\"")&&x.contains("\"dimension\":\"the_end\"")&&x.contains("\"yaw\":90.0"));}@Test void playerJsonEscapingIsValid()throws Exception{PlayerMarkerService s=new PlayerMarkerService();s.publish(List.of(new PlayerInfo("a\"b\\c\n","overworld",0,0,0,0)));assertTrue(c(new ApiPlayersHandler(s),"/api/players").body().contains("a\\\"b\\\\c\\n"));}@Test void biomeLookupSuccessReturnsPayload()throws Exception{TestHttpExchange e=c(b((a,x,z)->CompletableFuture.completedFuture("minecraft:plains"),true),"/api/biome?dim=overworld&x=1&z=2");assertEquals(200,e.s);assertTrue(e.body().contains("minecraft:plains"));}@Test void biomeLookupTimeoutReturns503()throws Exception{assertEquals(503,c(b((a,x,z)->new CompletableFuture<>(),true),"/api/biome?dim=overworld&x=1&z=2").s);}@Test void biomeLookupWithoutServerReturns503()throws Exception{assertEquals(503,c(b((a,x,z)->CompletableFuture.completedFuture("minecraft:plains"),false),"/api/biome?dim=overworld&x=1&z=2").s);}@Test void biomeLookupExceptionReturnsControlledFailure()throws Exception{CompletableFuture<String> f=new CompletableFuture<>();f.completeExceptionally(new RuntimeException());TestHttpExchange e=c(b((a,x,z)->f,true),"/api/biome?dim=overworld&x=1&z=2");assertEquals(503,e.s);assertFalse(e.body().contains("RuntimeException"));}@Test void biomeLookupUnknownDimensionIsRejected()throws Exception{assertEquals(400,c(b((a,x,z)->{fail();return null;},true),"/api/biome?dim=bad&x=1&z=2").s);}@Test void biomeHandlerWorksAfterWebServiceRecreation()throws Exception{assertEquals(200,c(b((a,x,z)->CompletableFuture.completedFuture("minecraft:forest"),true),"/api/biome?dim=overworld&x=1&z=2").s);}@Test void statusEnabledAndRunning()throws Exception{assertTrue(c(st(true,true),"/api/status").body().contains("\"serverRunning\":true"));}@Test void statusDisabledAndStopped()throws Exception{Files.writeString(d.resolve("forgewebmap-common.properties"),"enabled=false\n");assertTrue(c(st(false,false),"/api/status").body().contains("\"enabled\":false"));}@Test void statusReflectsStoppedRenderer()throws Exception{assertTrue(c(st(true,true),"/api/status").body().contains("\"renderState\":\"IDLE\""));}@Test void statusReflectsUnavailableServer()throws Exception{assertTrue(c(st(true,false),"/api/status").body().contains("\"serverRunning\":false"));}ApiStatusHandler st(boolean w,boolean s)throws Exception{WebMapConfig c=new WebMapConfig(d);c.load();return new ApiStatusHandler(c,new TileRenderManager(c),()->w,()->s);}}
